enum Message { case order(Order), ping(Ping)
    var key: String { switch self { case .order: return "order"; case .ping: return "ping" } } }
final class Router {
    private let lock = NSLock()
    private var rules: [String: (Message) -> Void] = [:]   // runtime rule base
    func publish(_ next: [String: (Message) -> Void]) { lock.withLock { rules = next } }
    func route(_ m: Message) {
        let snapshot = lock.withLock { rules }             // one snapshot per message
        (snapshot[m.key] ?? deadLetter)(m)
    }
}

